import type { DesignElement, DesignTemplate } from './editor-types';
import measuredGlyphs from './template-font-metrics.json' with { type: 'json' };
import photoManifest from './template-photo-manifest.json' with { type: 'json' };
import { wrapTemplateText } from './template-library.ts';

/** Independently authored, editable layouts. Photographs are the existing verified
 * offline CC0/public-domain collection; the gallery never fetches remote media. */
export const STUDIO_TEMPLATE_PROVENANCE = {
  name: 'Visro Studio Editions',
  layoutLicense: 'AGPL-3.0-only',
  source: 'Original layouts, fictional businesses and authored example content',
  media: 'Existing bundled CC0 and public-domain photographs with per-image metadata',
  requiresNetwork: false,
} as const;

export interface StudioTemplate extends DesignTemplate {
  composition: string;
  collection: string;
  edition: number;
  provenance: typeof STUDIO_TEMPLATE_PROVENANCE;
}
interface Palette { paper: string; ink: string; accent: string; soft: string; warm: string; heading: string }
const PALETTES: Palette[] = [
  { paper: '#f6f0e4', ink: '#263e35', accent: '#50725a', soft: '#dce4d4', warm: '#dcad63', heading: 'Playfair Display' },
  { paper: '#eef1f6', ink: '#253c5b', accent: '#4c6896', soft: '#d8e2ed', warm: '#c6a774', heading: 'League Spartan' },
  { paper: '#f8eee5', ink: '#59382f', accent: '#a8583d', soft: '#ecd4be', warm: '#e3b663', heading: 'Cormorant Garamond' },
  { paper: '#f2edf7', ink: '#382d55', accent: '#75519a', soft: '#dfd3ee', warm: '#d8b173', heading: 'DM Serif Display' },
];
const metrics = measuredGlyphs as Record<string, Record<string, Record<string, number>>>;
const rect = (x: number, y: number, width: number, height: number, fill: string, extra: Partial<DesignElement> = {}): DesignElement => ({ type: 'rect', x, y, width, height, fill, ...extra });
const circle = (x: number, y: number, size: number, fill: string, extra: Partial<DesignElement> = {}): DesignElement => ({ type: 'circle', x, y, width: size, height: size, fill, ...extra });
function text(value: string, x: number, y: number, width: number, height: number, size: number, fill: string, extra: Partial<DesignElement> = {}): DesignElement {
  const fontFamily = extra.fontFamily ?? 'DM Sans', fontWeight = extra.fontWeight ?? 400, lineHeight = extra.lineHeight ?? 1.19;
  const advances = metrics[fontFamily]?.[Number(fontWeight) >= 600 ? '700' : '400'];
  const units = (line: string) => [...line].reduce((sum, char) => sum + (advances?.[char] ?? .75), 0) + Math.max(0, line.length - 1) * (extra.letterSpacing ?? 0) / 1000;
  let fontSize = extra.fontSize ?? size, lines = wrapTemplateText(value, width, fontSize, fontFamily, fontWeight);
  while (fontSize > 16 && (fontSize * 1.13 * (1 + (lines.length - 1) * lineHeight) > height || lines.some(line => units(line) * fontSize > width * .96))) {
    fontSize--; lines = wrapTemplateText(value, width, fontSize, fontFamily, fontWeight);
  }
  return { type: 'text', x, y, width, height, fill, ...extra, fontFamily, fontWeight, fontSize, lineHeight, text: lines.join('\n') };
}
const title = (value: string, x: number, y: number, w: number, h: number, size: number, p: Palette, extra: Partial<DesignElement> = {}) => text(value, x, y, w, h, size, p.ink, { fontFamily: p.heading, fontWeight: 600, lineHeight: 1.02, ...extra });
const label = (value: string, x: number, y: number, w: number, p: Palette, extra: Partial<DesignElement> = {}) => text(value, x, y, w, 44, 18, p.ink, { fontWeight: 700, letterSpacing: 45, ...extra });
const rule = (x: number, y: number, w: number, p: Palette) => rect(x, y, w, 2, p.soft);
const photos = new Map(photoManifest.images.map(image => [image.id, image]));
function photo(id: string, x: number, y: number, width: number, height: number): DesignElement {
  const item = photos.get(id); if (!item) throw new Error(`Unknown Studio Edition photograph: ${id}`);
  return { type: 'image', x, y, width, height, name: item.description, src: `/template-photos/${item.file}`, imageFit: 'cover', source: { id: `commons:${item.commonsPageId}`, title: item.title, artist: item.author, license: item.license, licenseUrl: item.license === 'CC0' ? 'https://creativecommons.org/publicdomain/zero/1.0/' : 'https://commons.wikimedia.org/wiki/Help:Public_domain', sourceUrl: item.sourcePage } };
}
const footer = (brand: string, width: number, height: number, p: Palette, right = 'VISRO STUDIO EDITIONS') => [rule(60, height - 88, width - 120, p), label(brand, 60, height - 59, width * .58, p, { fontSize: 16 }), text(right, width * .58, height - 59, width * .42 - 60, 34, 16, p.ink, { align: 'right' })];
const checklist = (items: string[], x: number, y: number, width: number, step: number, p: Palette, size = 24) => items.flatMap((item, i) => [rect(x, y + i * step + 5, 18, 18, 'transparent', { stroke: p.accent, strokeWidth: 2, rx: 3, ry: 3 }), text(item, x + 36, y + i * step, width - 36, step - 7, size, p.ink)]);
const numbered = (items: string[], x: number, y: number, width: number, step: number, p: Palette) => items.flatMap((item, i) => [circle(x, y + i * step, 36, p.accent), text(String(i + 1).padStart(2, '0'), x + 3, y + i * step + 7, 30, 24, 17, p.paper, { align: 'center', fontWeight: 700 }), text(item, x + 57, y + i * step, width - 57, step - 8, 24, p.ink)]);
const library: StudioTemplate[] = [];
function add<T>(composition: string, name: string, category: string, width: number, height: number, briefs: readonly T[], render: (brief: T, p: Palette, i: number) => { brand: string; title: string; name?: string; description: string; elements: DesignElement[] }) {
  briefs.forEach((brief, i) => {
    const p = PALETTES[i], layout = render(brief, p, i);
    library.push({ id: `studio-original-${composition}-${i + 1}`, name: `${layout.brand} — ${layout.name ?? name}`, category, width, height, background: p.paper, palette: [p.paper, p.ink, p.accent, p.soft, p.warm], description: `${layout.description} Independently authored Studio Edition with editable text, shapes and photographs. Fictional example details.`, elements: layout.elements.map((element, index) => ({ ...element, name: element.name ?? (element.type === 'text' ? element.text?.replaceAll('\n', ' ').slice(0, 72) : `${layout.title} ${element.type} ${index + 1}`) })), composition, collection: layout.brand, edition: i + 1, provenance: STUDIO_TEMPLATE_PROVENANCE });
  });
}

