// Interleave different compositions and editorial palettes. A fresh gallery
// page shows different purposes and subjects instead of adjacent palette twins.
const compositionOrder = new Map([...new Set(library.map(template => template.composition))].map((id, index) => [id, index]));
const galleryRound = (template: StudioTemplate) => (template.edition - 1 - (compositionOrder.get(template.composition)! % 4) + 4) % 4;
export const STUDIO_TEMPLATE_LIBRARY: StudioTemplate[] = [...library].sort((a, b) => galleryRound(a) - galleryRound(b));
export const STUDIO_TEMPLATE_STATS = {
  count: STUDIO_TEMPLATE_LIBRARY.length,
  compositions: new Set(STUDIO_TEMPLATE_LIBRARY.map(template => template.composition)).size,
  collections: new Set(STUDIO_TEMPLATE_LIBRARY.map(template => template.collection)).size,
  photoLayouts: STUDIO_TEMPLATE_LIBRARY.filter(template => template.elements.some(element => element.type === 'image')).length,
  categories: [...new Set(STUDIO_TEMPLATE_LIBRARY.map(template => template.category))],
};
